<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class GroupController extends Controller {
 public function index(){return view('admin.groups.index',['groups'=>DB::table('study_groups as g')->leftJoin('teachers as t','t.id','=','g.curator_teacher_id')->leftJoin('specialties as sp','sp.id','=','g.specialty_id')->select('g.*','sp.code as specialty_code','sp.name as specialty_name',DB::raw("trim(coalesce(t.last_name,'')||' '||coalesce(t.first_name,'')||' '||coalesce(t.middle_name,'')) as curator"))->orderByDesc('g.active')->orderBy('g.name')->get()]);}
 public function create(){return view('admin.groups.form',['group'=>null,'teachers'=>$this->teachers(),'students'=>collect(),'specialties'=>$this->specialties()]);}
 public function store(Request $r){$d=$this->validated($r,true);$id=DB::table('study_groups')->insertGetId($d+['active'=>1,'is_visible'=>1,'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('admin.groups.edit',$id)->with('success','Группа создана');}
 public function edit($id){$g=DB::table('study_groups')->find($id);abort_if(!$g,404);return view('admin.groups.form',['group'=>$g,'teachers'=>$this->teachers(),'specialties'=>$this->specialties(),'students'=>DB::table('students')->where('current_group_id',$id)->where('status','active')->orderBy('last_name')->get()]);}
 public function update(Request $r,$id){abort_unless(DB::table('study_groups')->where('id',$id)->exists(),404);$d=$this->validated($r,false,$id);if($r->starosta_student_id)abort_unless(DB::table('students')->where('id',$r->starosta_student_id)->where('current_group_id',$id)->exists(),422,'Староста должен состоять в этой группе.');DB::table('study_groups')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Группа сохранена');}
 public function destroy($id){$g=DB::table('study_groups')->find($id);abort_if(!$g,404);$used=DB::table('students')->where('current_group_id',$id)->where('status','active')->exists();if($used)return back()->withErrors('Нельзя удалить группу с активными студентами. Сначала переведите студентов.');DB::table('study_groups')->where('id',$id)->update(['active'=>0,'is_visible'=>0,'updated_at'=>now()]);return redirect()->route('admin.groups.index')->with('success','Группа архивирована');}
 private function teachers(){return DB::table('teachers')->where('active',1)->orderBy('last_name')->get();}
 private function specialties(){return DB::table('specialties')->orderBy('code')->orderBy('name')->get();}
 private function validated(Request $r,$creating=false,$id=null){$rules=['name'=>'required|string|max:100','curator_teacher_id'=>'nullable|exists:teachers,id','starosta_student_id'=>'nullable|exists:students,id','specialty_id'=>'required|exists:specialties,id'];if($creating)$rules['name'].='|unique:study_groups,name';else $rules['name'].='|unique:study_groups,name,'.$id;return $r->validate($rules);}
}
